      /* ---- hub descriptions ---- */
      'hub.desc.air-hockey': 'Arrastra tu mazo, lanza el disco con física real y gana quien llegue a siete goles.',
      'hub.desc.ant-flap': 'La aventura de una pequeña hormiga voladora. Toca para aletear y pasa entre las ramas.',
      'hub.desc.ant-jump': 'Haz rebotar a la hormiga por plataformas infinitas, con algunas móviles, frágiles y elásticas.',
      'hub.desc.balloon-pop': 'Revienta globos, esquiva las bombas y encadena combos en 60 segundos.',
      'hub.desc.battleship': 'Coloca tu flota y caza cinco barcos enemigos ocultos. Tres niveles de IA y colocación aleatoria.',
      'hub.desc.block-drop': 'Bloques que caen, líneas perfectas. Cada vez más rápido: sobrevive y apila alto.',
      'hub.desc.bowling': 'Desliza hacia arriba para lanzar: apunta, añade efecto y busca los 300 perfectos.',
      'hub.desc.breakout': 'Rompe todos los ladrillos con una física de pala milimétrica. Tres vidas, niveles infinitos.',
      'hub.desc.checkers': 'Capturas obligatorias, saltos en cadena y coronaciones contra una máquina que calcula de verdad.',
      'hub.desc.gem-match': 'Intercambia gemas vecinas, alinea tres o más y encadena combos para más puntos.',
      'hub.desc.gomoku': 'El clásico cinco en línea contra una computadora en un tablero de 15×15.',
      'hub.desc.hanoi': 'Lleva la torre entera a la última varilla, disco a disco: 5 niveles y deshacer ilimitado.',
      'hub.desc.helicopter': 'Mantén pulsado para subir por una cueva sin fin que se estrecha. Un roce con la roca y se acaba.',
      'hub.desc.helix-drop': 'Gira la torre helicoidal para que la bola caiga por cada hueco: los tramos rojos acaban la partida.',
      'hub.desc.hoop-shot': 'Arrastra hacia atrás, suelta y encesta en un aro en movimiento. 60 segundos, combos y sin defensa.',
      'hub.desc.lights-out': 'Toca una luz para girarla junto a sus cuatro vecinas y apágalas todas. Cada tablero tiene solución.',
      'hub.desc.mahjong-link': 'Empareja fichas iguales con un camino de dos giros como máximo. Diez niveles con tiempo y sin bloqueos.',
      'hub.desc.mancala': 'Siembra semillas, captura desde hoyos vacíos y gana turnos extra en este tablero clásico.',
      'hub.desc.maze-muncher': 'Cómete todos los puntos, esquiva a cuatro fantasmas y usa una píldora para contraatacar.',
      'hub.desc.mini-golf': 'Nueve hoyos hechos a mano: arrastra atrás, suelta y putt entre arena, agua y muros.',
      'hub.desc.nonogram': 'Usa las pistas numéricas para rellenar la cuadrícula. 12 niveles con solución única.',
      'hub.desc.paddle-duel': 'Duelo de palas estilo Pong contra la IA en tres dificultades. Gana el primero en llegar a 7.',
      'hub.desc.penalty-kick': 'Lanza y ataja en una tanda de cinco rondas: engaña al portero y adivina el córner.',
      'hub.desc.pipe-connect': 'Gira las tuberías hasta que el agua llegue a la salida: 12 niveles, todos resolubles.',
      'hub.desc.reversi': 'Rodea las fichas del rival para voltearlas. Tres niveles de IA y jugadas legales resaltadas.',
      'hub.desc.rush-hour': 'Aparta los coches que bloquean y saca el coche rojo del atasco 6x6. 12 niveles generados, todos con solución.',
      'hub.desc.simon-says': 'Mira las cuatro luces y repite el patrón. Un paso más en cada ronda.',
      'hub.desc.slingshot': 'Estira la goma, sigue la trayectoria punteada y suelta: el centro vale 100.',
