      /* ---- hub descriptions ---- */
      'hub.desc.air-hockey': 'Faites glisser votre maillet, tirez le palet avec une vraie physique : premier à sept buts.',
      'hub.desc.ant-flap': 'L\'aventure d\'une petite fourmi volante. Touchez pour battre des ailes et passez entre les branches.',
      'hub.desc.ant-jump': 'Faites rebondir la fourmi sur des plateformes à l\'infini, dont des mobiles, fragiles et élastiques.',
      'hub.desc.balloon-pop': 'Éclatez les ballons, évitez les bombes et enchaînez les combos en 60 secondes.',
      'hub.desc.battleship': 'Placez votre flotte puis traquez cinq navires ennemis cachés. Trois niveaux d\'IA, placement aléatoire.',
      'hub.desc.block-drop': 'Des blocs qui tombent, des lignes parfaites. Ça accélère : survivez et empilez haut.',
      'hub.desc.bowling': 'Glissez vers le haut pour lancer : visez, ajoutez de l\'effet et visez le 300 parfait.',
      'hub.desc.breakout': 'Détruisez toutes les briques grâce à une physique de raquette au millimètre. Trois vies, niveaux infinis.',
      'hub.desc.checkers': 'Prises obligatoires, rafles en chaîne et dames couronnées face à un ordinateur qui calcule vraiment.',
      'hub.desc.gem-match': 'Échangez des gemmes voisines, alignez-en trois ou plus et enchaînez les combos.',
      'hub.desc.gomoku': 'Le classique du cinq en ligne contre l\'ordinateur sur un plateau 15×15.',
      'hub.desc.hanoi': 'Déplacez toute la tour vers la dernière tige, un disque à la fois : 5 niveaux, annulation illimitée.',
      'hub.desc.helicopter': 'Maintenez pour monter dans une grotte sans fin qui se rétrécit. Un contact avec la roche et c\'est fini.',
      'hub.desc.helix-drop': 'Faites tourner la tour hélicoïdale pour que la bille passe par chaque ouverture : les segments rouges terminent la partie.',
      'hub.desc.hoop-shot': 'Tirez vers l\'arrière, relâchez et marquez dans un panier mobile. 60 secondes, combos, sans défense.',
      'hub.desc.lights-out': 'Touchez une lampe pour la basculer avec ses quatre voisines et éteignez-les toutes. Chaque grille a une solution.',
      'hub.desc.mahjong-link': 'Associez des tuiles identiques avec un chemin de deux virages au plus. Dix niveaux chronométrés, jamais bloqués.',
      'hub.desc.mancala': 'Semez, capturez depuis des trous vides et gagnez des tours bonus sur ce plateau classique.',
      'hub.desc.maze-muncher': 'Mangez tous les points, évitez quatre fantômes et croquez une pastille pour riposter.',
      'hub.desc.mini-golf': 'Neuf trous faits main : tirez en arrière, lâchez et puttez entre sable, eau et murs.',
      'hub.desc.nonogram': 'Utilisez les indices numériques pour remplir la grille. 12 niveaux à solution unique.',
      'hub.desc.paddle-duel': 'Duel de raquettes façon Pong contre l\'IA, trois difficultés. Le premier à 7 gagne.',
      'hub.desc.penalty-kick': 'Tirez et arrêtez lors d\'une séance de cinq tirs : trompez le gardien, puis devinez le bon coin.',
      'hub.desc.pipe-connect': 'Faites pivoter les tuyaux jusqu\'à ce que l\'eau atteigne la sortie : 12 niveaux, tous solvables.',
      'hub.desc.reversi': 'Encerclez les pions adverses pour les retourner. Trois niveaux d\'IA, coups légaux surlignés.',
      'hub.desc.rush-hour': 'Écartez les voitures qui bloquent et faites sortir la voiture rouge du parking 6x6. 12 niveaux générés, tous solubles.',
      'hub.desc.simon-says': 'Regardez les quatre lumières et répétez la séquence. Un pas de plus à chaque manche.',
      'hub.desc.slingshot': 'Tendez l\'élastique, suivez la trajectoire en pointillés et lâchez : le centre vaut 100.',
      'hub.desc.snake': 'Le classique intemporel. Mangez, grandissez, accélérez — sans vous mordre.',
      'hub.desc.2048': 'Glissez et fusionnez les tuiles. Atteignez 2048, puis continuez.',
      'hub.desc.minesweeper': 'Trois difficultés, premier clic toujours sûr. Marquez les mines et dégagez le terrain.',
      'hub.desc.snakes-ladders': 'Lancez le dé et coursez la CPU jusqu\'à la case 100 : les échelles montent, les serpents ramènent.',
      'hub.desc.sokoban': 'Poussez chaque caisse sur une cible. 30 niveaux, annulation illimitée, alerte de blocage.',
      'hub.desc.star-defender': 'Des vagues d\'ennemis sans fin. Tirez, esquivez, survivez le plus longtemps possible.',
      'hub.desc.water-sort': 'Versez les liquides colorés d\'un tube à l\'autre jusqu\'à ce que chaque tube n\'ait plus qu\'une seule couleur. Chaque partie est vérifiée comme soluble.',

