      /* ---- hub descriptions ---- */
      'hub.desc.air-hockey': 'Zieh deinen Schläger, schieße den Puck mit echter Physik — wer zuerst sieben Tore hat, gewinnt.',
      'hub.desc.ant-flap': 'Das Abenteuer einer kleinen fliegenden Ameise. Tippe zum Flattern und schlüpfe durch die Zweige.',
      'hub.desc.ant-jump': 'Lass die Ameise über endlose Plattformen hüpfen — manche bewegen sich, brechen weg oder federn.',
      'hub.desc.balloon-pop': 'Lass alle Ballons platzen, meide die Bomben und sammle Combos in 60 Sekunden.',
      'hub.desc.battleship': 'Stelle deine Flotte auf und jage fünf versteckte Schiffe. Drei KI-Stufen, Zufallsaufstellung per Tipp.',
      'hub.desc.block-drop': 'Fallende Blöcke, perfekte Reihen. Es wird immer schneller: überlebe und staple hoch.',
      'hub.desc.bowling': 'Wische nach oben und wirf: ziele, gib Spin dazu und jage die perfekte 300.',
      'hub.desc.breakout': 'Zertrümmere jeden Stein mit millimetergenauer Schlägerphysik. Drei Leben, endlose Levels.',
      'hub.desc.checkers': 'Schlagzwang, Kettenzüge und Damenkrönung gegen einen Computer, der wirklich vorausrechnet.',
      'hub.desc.gem-match': 'Tausche benachbarte Edelsteine, reihe drei oder mehr auf und kette Combos für Bonuspunkte.',
      'hub.desc.gomoku': 'Der Klassiker Fünf in einer Reihe gegen den Computer auf einem 15×15-Brett.',
      'hub.desc.hanoi': 'Bringe den ganzen Turm Stab für Stab zur letzten Stange — 5 Level, unbegrenzt rückgängig.',
      'hub.desc.helicopter': 'Halte gedrückt und steige durch eine endlose, immer engere Höhle. Eine Berührung des Felsens beendet den Flug.',
      'hub.desc.helix-drop': 'Dreh den Wendelturm, damit die Kugel durch jede Lücke fällt – rote Segmente beenden den Lauf.',
      'hub.desc.hoop-shot': 'Nach hinten ziehen, loslassen und in einen beweglichen Korb treffen. 60 Sekunden, Combos, keine Verteidigung.',
      'hub.desc.lights-out': 'Tippe ein Licht an, um es mit seinen vier Nachbarn umzuschalten, und schalte alle aus. Jedes Rätsel ist lösbar.',
      'hub.desc.mahjong-link': 'Paare gleiche Steine mit höchstens zwei Kurven. Zehn Levels auf Zeit, nie blockiert.',
      'hub.desc.mancala': 'Säe Samen, fange aus leeren Mulden und gewinne Extrazüge auf diesem klassischen Brett.',
      'hub.desc.maze-muncher': 'Frisst alle Punkte, weicht vier Geistern aus und fresst mit einer Kraftpille zurück.',
      'hub.desc.mini-golf': 'Neun handgebaute Löcher — zieh zurück, lass los und putte um Sand, Wasser und Wände.',
      'hub.desc.nonogram': 'Fülle das Gitter mit den Zahlenhinweisen. 12 Level, jedes mit eindeutiger Lösung.',
      'hub.desc.paddle-duel': 'Pong-artiges Schlägerduell gegen die KI in drei Schwierigkeiten. Wer zuerst 7 hat, gewinnt.',
      'hub.desc.penalty-kick': 'Schieße und halte im Fünfer-Schießen: überliste den Torwart und errate die richtige Ecke.',
      'hub.desc.pipe-connect': 'Drehe die Rohre, bis das Wasser am Auslass ankommt — 12 Level, jedes lösbar.',
      'hub.desc.reversi': 'Umzingle gegnerische Steine und drehe sie um. Drei KI-Stufen, gültige Züge markiert.',
      'hub.desc.rush-hour': 'Schiebe die blockierenden Autos zur Seite und fahre das rote Auto aus dem 6x6-Stau. 12 Level, alle lösbar.',
      'hub.desc.simon-says': 'Beobachte die vier Lichter und wiederhole das Muster. Jede Runde ein Schritt mehr.',
      'hub.desc.slingshot': 'Spann das Band, folge der gepunkteten Flugbahn und lass los – Volltreffer bringt 100.',
      'hub.desc.snake': 'Der Klassiker schlechthin. Friss, wachse, werde schneller — nur beiß dich nicht selbst.',
      'hub.desc.2048': 'Schiebe und verschmelze die Kacheln. Erreiche 2048 und spiel weiter.',
      'hub.desc.minesweeper': 'Drei Schwierigkeiten, erster Klick immer sicher. Markiere die Minen und räume das Feld.',
      'hub.desc.snakes-ladders': 'Würfle gegen die CPU bis Feld 100 — Leitern bringen dich hoch, Schlangen ziehen dich zurück.',
      'hub.desc.sokoban': 'Schiebe jede Kiste auf ein Zielfeld. 30 Level, unbegrenzt rückgängig, Blockier-Warnung.',
      'hub.desc.star-defender': 'Eine Welle nach der anderen. Schießen, ausweichen, so lange wie möglich überleben.',
      'hub.desc.water-sort': 'Gieße die farbigen Flüssigkeiten zwischen den Röhrchen um, bis jedes nur noch eine Farbe enthält. Jede Aufgabe ist als lösbar geprüft.',

