      /* ---- hub descriptions ---- */
      'hub.desc.air-hockey': '말렛을 드래그해 실제 물리로 슛하세요. 먼저 7골을 넣으면 승리합니다.',
      'hub.desc.ant-flap': '작은 날아다니는 개미의 모험. 눌러서 날갯짓하고 나뭇가지 사이를 통과하세요.',
      'hub.desc.ant-jump': '개미가 끝없이 플랫폼을 튕겨 올라갑니다. 움직이는 발판, 부서지는 발판, 스프링을 조심하세요.',
      'hub.desc.balloon-pop': '60초 동안 풍선을 터뜨리고 폭탄을 피해 콤보를 쌓으세요.',
      'hub.desc.battleship': '함대를 배치하고 숨겨진 적함 5척을 찾아내세요. AI 3단계, 랜덤 배치 한 번에.',
      'hub.desc.block-drop': '떨어지는 블록을 지우고 쌓아 올리세요. 점점 빨라집니다.',
      'hub.desc.bowling': '위로 스와이프해 투구하세요. 조준과 회전을 조절해 퍼펙트 300에 도전.',
      'hub.desc.breakout': '패들 각도를 정확히 맞춰 모든 벽돌을 부수세요. 목숨 3개, 무한 스테이지.',
      'hub.desc.checkers': '잡기 필수, 연속 잡기, 승진까지. 진짜로 앞을 읽는 컴퓨터와 두는 체커.',
      'hub.desc.gem-match': '이웃한 보석을 바꿔 3개 이상 맞추고 연쇄로 보너스 점수를 노리세요.',
      'hub.desc.gomoku': '15×15 보드에서 컴퓨터와 대결하는 클래식 오목.',
      'hub.desc.hanoi': '원반을 하나씩 옮겨 탑을 마지막 기둥으로 — 5개 레벨, 무제한 되돌리기.',
      'hub.desc.helicopter': '누르고 있으면 상승합니다. 점점 좁아지는 동굴을 통과하세요. 암벽에 닿으면 끝납니다.',
      'hub.desc.helix-drop': '나선 탑을 돌려 공이 각 층의 틈으로 떨어지게 하세요. 빨간 부분에 닿으면 끝납니다.',
      'hub.desc.hoop-shot': '뒤로 드래그했다 놓아 움직이는 골대에 슛을 넣으세요. 60초, 콤보 배율, 수비 없음.',
      'hub.desc.lights-out': '불을 누르면 자기 자신과 상하좌우가 함께 바뀝니다. 모두 끄면 클리어. 모든 판은 반드시 풀 수 있습니다.',
      'hub.desc.mahjong-link': '같은 패를 두 번 이내로 꺾는 길로 연결해 지웁니다. 제한 시간 10단계, 막히지 않습니다.',
      'hub.desc.mancala': '씨앗을 뿌리고 빈 구덩이에서 획득하며 추가 차례를 얻는 클래식 만칼라.',
      'hub.desc.maze-muncher': '점을 모두 먹고 유령 넷을 피하세요. 파워 알약을 먹으면 반격할 수 있습니다.',
      'hub.desc.mini-golf': '직접 만든 9개 홀 — 뒤로 당겼다 놓아 퍼팅하세요. 모래, 물, 벽을 피해 보세요.',
      'hub.desc.nonogram': '숫자 힌트로 칸을 채우세요. 12개 레벨 모두 유일한 해를 검증했습니다.',
      'hub.desc.paddle-duel': 'Pong 스타일 패들 대결, AI와 3단계 난이도. 먼저 7점을 낸 쪽이 승리.',
      'hub.desc.penalty-kick': '5라운드 승부차기에서 슛과 선방을 모두 — 골키퍼를 속이고 상대의 코너를 읽으세요.',
      'hub.desc.pipe-connect': '관을 돌려 물을 출구까지 연결하세요 — 12개 레벨, 모두 풀 수 있습니다.',
      'hub.desc.reversi': '상대 돌을 사이에 끼워 뒤집으세요. AI 3단계, 놓을 수 있는 곳은 강조 표시.',
      'hub.desc.rush-hour': '가로막은 차를 밀어내고 빨간 차를 6x6 주차장 밖으로 빼내세요. 12개 레벨 모두 풀 수 있습니다.',
      'hub.desc.simon-says': '네 개의 불빛 순서를 기억해 그대로 눌러 보세요. 라운드마다 하나씩 늘어납니다.',
      'hub.desc.slingshot': '고무줄을 당겨 점선 궤적을 확인하고 놓으세요. 정중앙은 100점입니다.',
      'hub.desc.snake': '영원한 고전. 먹고, 자라나고, 빨라집니다 — 자기 몸만 물지 마세요.',
      'hub.desc.2048': '타일을 밀어 합치세요. 2048을 만들고 계속 도전하세요.',
      'hub.desc.minesweeper': '3단계 난이도, 첫 클릭은 항상 안전. 지뢰에 깃발을 꽂고 모두 열어보세요.',
      'hub.desc.snakes-ladders': '주사위를 굴려 CPU와 100번 칸까지 경주하세요. 사다리는 올라가고 뱀은 끌어내립니다.',
      'hub.desc.sokoban': '상자를 모두 목표 칸으로. 30개 레벨, 무제한 되돌리기, 막힘 알림.',
      'hub.desc.star-defender': '끝없이 밀려오는 적들. 쏘고 피하고 최대한 오래 살아남으세요.',
      'hub.desc.water-sort': '색깔 액체를 시험관 사이로 옮겨 모든 시험관이 한 가지 색만 담도록 만드세요. 모든 문제는 풀 수 있음을 검증했습니다.',

